document.addEventListener('change',async e=>{const t=e.target,f=t.closest('form');if(t.matches('input[type=file]')){try{const blob=await compress(t.files[0]);if(f.id==='signup-form'){state.signupPhoto=blob;state.signupAvatar=''}else{pendingPhoto=blob;state.photoChoice='';photoRemove=false}const url=URL.createObjectURL(blob);$('#photo-preview').innerHTML=`<img class="avatar large" src="${url}" alt="Square-cropped preview"><small>Center crop preview</small>`;f.querySelectorAll('.avatar-opt').forEach(x=>x.classList.remove('selected'))}catch(err){toast(err.message,true)}return}if(t.name==='campus'&&f?.college){const list=f.querySelector('#college-options');if(list)list.innerHTML=[...(CAMPUSES[t.value]||[]),'Other / Not Applicable'].map(v=>`<option value="${E(v)}"></option>`).join('');}if(t.name==='affiliation'&&f?.year_level&&t.value!=='Student')f.year_level.value='Not Applicable';if(f?.id==='op-form'){state.form.dirty=true;updateConditional(f);const fd=new FormData(f),ev={};for(const k of NEU_CRITERIA){const code=fd.get('e_'+k),url=fd.get('url_'+k);if(code&&validEvidenceURL(url))ev[k]={code,source_url:url}}const sc=neuScore({evidence:ev},state.settings),el=f.querySelector('#rubric-preview');if(el)el.textContent=sc.score===null?`Not assessed · ${sc.assessment.missing.length} criteria need evidence.`:`Preview: ${sc.score.toFixed(1)}/100 · ${sc.priority}`}if(t.dataset.filter){const k=t.dataset.filter,v=t.value;state.filters[k]=t.checked?[...new Set([...(state.filters[k]||[]),v])]:(state.filters[k]||[]).filter(x=>x!==v);state.pg=1;$('#discover-results').innerHTML=discoverResults()}if(['picker-category','picker-scope'].includes(t.id))$('#picker-results').innerHTML=pickerResults($('#picker-search').value);if(t.id==='show-closed'){state.showClosed=t.checked;state.pg=1;$('#discover-results').innerHTML=discoverResults()}if(t.id==='compare-diff'){state.diff=t.checked;render()}if(t.name==='sort'){state.sort=t.value;state.pg=1;$('#discover-results').innerHTML=discoverResults()}const map={'manage-sector':'ms','manage-status':'mstatus','user-role':'ur','user-campus':'uc','user-college':'ucl','user-status':'us','log-date':'ld','log-action':'la'};if(map[t.name]){state[map[t.name]]=t.value;const key=t.name.split('-')[0];if(key==='manage')state.mpg=1;if(key==='user')state.upg=1;$('#'+key+'-results').innerHTML=({manage:manageResults,user:userResults,log:logResults}[key])()}if(t.type==='checkbox'&&t.checked&&f&&['survey-form','op-form'].includes(f.id)){const exclusive=['None','Not Disclosed','Not Applicable','None Yet','None — I need support','Not Sure Yet'];f.querySelectorAll('input[type=checkbox]').forEach(x=>{if(x!==t&&x.name===t.name&&(exclusive.includes(t.value)||exclusive.includes(x.value)))x.checked=false})}});
document.addEventListener('input',e=>{const t=e.target;if(t.closest('#op-form')&&state.form)state.form.dirty=true;if(t.tagName==='TEXTAREA'){const c=t.parentElement.querySelector('[data-counter]');if(c)c.textContent=`${t.value.length} / ${t.maxLength} characters`}if(t.id==='discover-search'){state.q=t.value;state.pg=1;$('#discover-results').innerHTML=discoverResults()}if(t.id==='picker-search')$('#picker-results').innerHTML=pickerResults(t.value);if(t.id==='saved-search')$('#saved-results').innerHTML=savedResults(t.value);if(t.id==='manage-search'){state.mq=t.value;state.mpg=1;$('#manage-results').innerHTML=manageResults()}if(t.id==='user-search'){state.uq=t.value;state.upg=1;$('#user-results').innerHTML=userResults()}if(t.id==='log-search'){state.lq=t.value;$('#log-results').innerHTML=logResults()}});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&state.form?.dirty){e.preventDefault();const [p,id='']=a.getAttribute('href').slice(1).split('/');route(p,id)}});window.addEventListener('hashchange',()=>{if(state.me&&!location.hash.includes('access_token=')){state.bell=false;render();window.scrollTo(0,0)}});window.addEventListener('beforeunload',e=>{if(state.form?.dirty){e.preventDefault();e.returnValue=''}});document.addEventListener('error',e=>{if(e.target.matches?.('img[data-avatar-fallback]')){const span=document.createElement('span');span.className=e.target.className;span.textContent=e.target.dataset.avatarFallback;e.target.replaceWith(span)}},true);setInterval(()=>{if(state.me&&!document.hidden){rpc('goid_deadline_reminders').catch(()=>{});load({quiet:true})}},60000);boot();
